import{_ as e,o as a,c as d,ai as r}from"./chunks/framework.DQi1ytmF.js";const m=JSON.parse('{"title":"Effect compatibility and maturity","description":"","frontmatter":{},"headers":[],"relativePath":"resources/effect-compatibility.md","filePath":"resources/effect-compatibility.md"}'),o={name:"resources/effect-compatibility.md"};function i(c,t,n,s,f,l){return a(),d("div",null,[...t[0]||(t[0]=[r('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /craft/resources/effect-compatibility.md for this page in Markdown format</div><h1 id="effect-compatibility-and-maturity" tabindex="-1">Effect compatibility and maturity <a class="header-anchor" href="#effect-compatibility-and-maturity" aria-label="Permalink to &quot;Effect compatibility and maturity&quot;">​</a></h1><p>This page describes the current repository contract. It is a decision aid for teams evaluating CraftTS, not a promise that beta APIs will remain unchanged.</p><h2 id="compatibility-matrix" tabindex="-1">Compatibility matrix <a class="header-anchor" href="#compatibility-matrix" aria-label="Permalink to &quot;Compatibility matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Current contract</th><th>Status</th></tr></thead><tbody><tr><td>Craft runtime</td><td><code>@craft-ts/core</code> <code>0.7.0-beta.11</code></td><td>Beta</td></tr><tr><td>Craft components</td><td><code>@craft-ts/component</code> on the same Craft version</td><td>Beta</td></tr><tr><td>Effect bridge</td><td><code>@craft-ts/effect</code> <code>0.7.0-beta.11</code></td><td>Beta / experimental integration</td></tr><tr><td>Effect runtime</td><td><code>effect</code> <code>^4.0.0-rc.112</code></td><td>Effect 4 release candidate required by current Alchemy</td></tr><tr><td>Effect 3 projects</td><td>No compatibility contract</td><td>Migrate or isolate before adopting</td></tr><tr><td>Node.js</td><td>20.19+ or 22.12+</td><td>Required by the current docs</td></tr><tr><td>TypeScript</td><td>Use the version supported by the selected Craft beta; verify with the project lockfile</td><td>Toolchain-sensitive</td></tr><tr><td>Browser application</td><td>Vite demo and jsdom tests are covered</td><td>Experimental but executable</td></tr><tr><td>SSR</td><td>No product SSR renderer in this release</td><td>Not ready</td></tr><tr><td>Server functions</td><td>Local transport and middleware experiment</td><td>Proof of concept</td></tr><tr><td>Migration tooling</td><td><code>craft-migrate</code> for Craft concepts</td><td>No complete Effect-specific migration</td></tr></tbody></table><p>Install all Craft packages from the same beta channel. <code>@craft-ts/effect</code> also declares <code>effect</code> as a peer dependency, so the Effect version is part of the application&#39;s compatibility surface.</p><h2 id="maturity-by-capability" tabindex="-1">Maturity by capability <a class="header-anchor" href="#maturity-by-capability" aria-label="Permalink to &quot;Maturity by capability&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>What is covered today</th><th>Adoption guidance</th></tr></thead><tbody><tr><td>Effect domain programs</td><td><code>Effect</code>, tagged errors, <code>Context.Service</code>, <code>Layer</code></td><td>Good candidate for a pilot</td></tr><tr><td>Effect-backed reads and writes</td><td><code>queryEffect</code>, <code>mutationEffect</code>, <code>asyncProcessEffect</code></td><td>Pilot with real tests and a narrow feature</td></tr><tr><td>Synchronous Effect members in a computation</td><td><code>SyncOp</code>, <code>computedEffect</code>, <code>syncEffect</code></td><td>Declare the members that never suspend, then reuse them in <code>craftComputed</code> and <code>params</code></td></tr><tr><td>Layer scoping</td><td>application, route, component and primitive providers</td><td>Use after the basic boundary is understood</td></tr><tr><td>Typed error mapping</td><td><code>E</code> becomes Craft exceptions; defects stay technical errors</td><td>Suitable for explicit UI error handling</td></tr><tr><td>Effect service mocks</td><td><code>mockEffectService</code> plus Craft registers</td><td>Suitable for focused tests</td></tr><tr><td>Static Effect graph</td><td>Effect services, operations and Layers are collected</td><td>Useful for architecture rules; still evolving</td></tr><tr><td>Server functions</td><td><code>executeEffect</code>, middleware and local HTTP demo</td><td>Keep behind an experimental boundary</td></tr><tr><td>SSR and deployment integration</td><td>Not shipped as a product contract</td><td>Do not make it a prerequisite for adoption</td></tr></tbody></table><h2 id="how-to-read-this-table" tabindex="-1">How to read this table <a class="header-anchor" href="#how-to-read-this-table" aria-label="Permalink to &quot;How to read this table&quot;">​</a></h2><p>The safest first adoption is browser-side, one feature, with an existing Effect domain and an application Layer provided by Craft. Defer SSR-specific decisions and server functions until their contracts are stable.</p><p>See <a href="/craft/resources/effect-adoption.html">Adopting CraftTS progressively</a> for a staged plan and <a href="/craft/learn-effect/00-start-here.html#5-verify-the-boundary">the quickstart&#39;s verification section</a> for the executable Effect demo checks.</p>',11)])])}const h=e(o,[["render",i]]);export{m as __pageData,h as default};
